import io
import unittest
from unittest import mock
from grep import grep
from public_test import FILE_TEXT, open_mock

@mock.patch("grep.open", name="open", side_effect=open_mock, create=True)
class ComprehensiveGrepTest(unittest.TestCase):
    # Single file tests
    def test_one_file_one_match_no_flags(self, mock_open):
        self.assertEqual(
            grep("Agamemnon", "", ["iliad.txt"]),
            "Of Atreus, Agamemnon, King of men.\n"
        )

    def test_one_file_one_match_print_line_numbers(self, mock_open):
        self.assertEqual(
            grep("Forbidden", "-n", ["paradise-lost.txt"]),
            "2:Of that Forbidden Tree, whose mortal tast\n"
        )

    def test_one_file_one_match_case_insensitive(self, mock_open):
        self.assertEqual(
            grep("FORBIDDEN", "-i", ["paradise-lost.txt"]),
            "Of that Forbidden Tree, whose mortal tast\n"
        )

    def test_one_file_one_match_print_file_names(self, mock_open):
        self.assertEqual(
            grep("Forbidden", "-l", ["paradise-lost.txt"]),
            "paradise-lost.txt\n"
        )

    def test_one_file_one_match_match_entire_lines(self, mock_open):
        self.assertEqual(
            grep("With loss of Eden, till one greater Man", "-x", ["paradise-lost.txt"]),
            "With loss of Eden, till one greater Man\n"
        )

    def test_one_file_one_match_multiple_flags(self, mock_open):
        self.assertEqual(
            grep("OF ATREUS, Agamemnon, KING OF MEN.", "-n -i -x", ["iliad.txt"]),
            "9:Of Atreus, Agamemnon, King of men.\n"
        )

    def test_one_file_several_matches_no_flags(self, mock_open):
        self.assertEqual(
            grep("may", "", ["midsummer-night.txt"]),
            "Nor how it may concern my modesty,\n"
            "But I beseech your grace that I may know\n"
            "The worst that may befall me in this case,\n"
        )

    def test_one_file_several_matches_print_line_numbers(self, mock_open):
        self.assertEqual(
            grep("may", "-n", ["midsummer-night.txt"]),
            "3:Nor how it may concern my modesty,\n"
            "5:But I beseech your grace that I may know\n"
            "6:The worst that may befall me in this case,\n"
        )

    def test_one_file_several_matches_match_entire_lines(self, mock_open):
        self.assertEqual(
            grep("may", "-x", ["midsummer-night.txt"]),
            ""
        )

    def test_one_file_several_matches_case_insensitive(self, mock_open):
        self.assertEqual(
            grep("ACHILLES", "-i", ["iliad.txt"]),
            "Achilles sing, O Goddess! Peleus' son;\n"
            "The noble Chief Achilles from the son\n"
        )

    def test_one_file_several_matches_invert(self, mock_open):
        self.assertEqual(
            grep("Of", "-v", ["paradise-lost.txt"]),
            "Brought Death into the World, and all our woe,\n"
            "With loss of Eden, till one greater Man\n"
            "Restore us, and regain the blissful Seat,\n"
            "Sing Heav'nly Muse, that on the secret top\n"
            "That Shepherd, who first taught the chosen Seed\n"
        )

    def test_one_file_no_matches_various_flags(self, mock_open):
        self.assertEqual(
            grep("Gandalf", "-n -l -x -i", ["iliad.txt"]),
            ""
        )

    def test_one_file_one_match_file_flag_takes_precedence(self, mock_open):
        self.assertEqual(
            grep("ten", "-n -l", ["iliad.txt"]),
            "iliad.txt\n"
        )

    def test_one_file_several_matches_invert_and_match_entire(self, mock_open):
        expected = "".join(
            line for line in FILE_TEXT["iliad.txt"].splitlines(keepends=True)
            if line.strip("\n\r") != "Illustrious into Ades premature,"
        )
        self.assertEqual(
            grep("Illustrious into Ades premature,", "-x -v", ["iliad.txt"]),
            expected
        )

    # Multiple files tests
    def test_multiple_files_one_match_no_flags(self, mock_open):
        self.assertEqual(
            grep("Agamemnon", "", ["iliad.txt", "midsummer-night.txt", "paradise-lost.txt"]),
            "iliad.txt:Of Atreus, Agamemnon, King of men.\n"
        )

    def test_multiple_files_several_matches_no_flags(self, mock_open):
        self.assertEqual(
            grep("may", "", ["iliad.txt", "midsummer-night.txt", "paradise-lost.txt"]),
            "midsummer-night.txt:Nor how it may concern my modesty,\n"
            "midsummer-night.txt:But I beseech your grace that I may know\n"
            "midsummer-night.txt:The worst that may befall me in this case,\n"
        )

    def test_multiple_files_several_matches_print_line_numbers(self, mock_open):
        self.assertEqual(
            grep("that", "-n", ["iliad.txt", "midsummer-night.txt", "paradise-lost.txt"]),
            "midsummer-night.txt:5:But I beseech your grace that I may know\n"
            "midsummer-night.txt:6:The worst that may befall me in this case,\n"
            "paradise-lost.txt:2:Of that Forbidden Tree, whose mortal tast\n"
            "paradise-lost.txt:6:Sing Heav'nly Muse, that on the secret top\n"
        )

    def test_multiple_files_one_match_print_file_names(self, mock_open):
        self.assertEqual(
            grep("who", "-l", ["iliad.txt", "midsummer-night.txt", "paradise-lost.txt"]),
            "iliad.txt\n"
            "paradise-lost.txt\n"
        )

    def test_multiple_files_several_matches_case_insensitive(self, mock_open):
        self.assertEqual(
            grep("TO", "-i", ["iliad.txt", "midsummer-night.txt", "paradise-lost.txt"]),
            "iliad.txt:Caused to Achaia's host, sent many a soul\n"
            "iliad.txt:Illustrious into Ades premature,\n"
            "iliad.txt:And Heroes gave (so stood the will of Jove)\n"
            "iliad.txt:To dogs and to all ravening fowls a prey,\n"
            "midsummer-night.txt:I do entreat your grace to pardon me.\n"
            "midsummer-night.txt:In such a presence here to plead my thoughts;\n"
            "midsummer-night.txt:If I refuse to wed Demetrius.\n"
            "paradise-lost.txt:Brought Death into the World, and all our woe,\n"
            "paradise-lost.txt:Restore us, and regain the blissful Seat,\n"
            "paradise-lost.txt:Sing Heav'nly Muse, that on the secret top\n"
        )

    def test_multiple_files_several_matches_invert(self, mock_open):
        self.assertEqual(
            grep("a", "-v", ["iliad.txt", "midsummer-night.txt", "paradise-lost.txt"]),
            "iliad.txt:Achilles sing, O Goddess! Peleus' son;\n"
            "iliad.txt:The noble Chief Achilles from the son\n"
            "midsummer-night.txt:If I refuse to wed Demetrius.\n"
        )

    def test_multiple_files_one_match_match_entire_lines(self, mock_open):
        self.assertEqual(
            grep("With loss of Eden, till one greater Man", "-x", ["iliad.txt", "midsummer-night.txt", "paradise-lost.txt"]),
            "paradise-lost.txt:With loss of Eden, till one greater Man\n"
        )

    def test_multiple_files_one_match_multiple_flags(self, mock_open):
        self.assertEqual(
            grep("WITH LOSS OF EDEN, TILL ONE GREATER MAN", "-n -i -x", ["iliad.txt", "midsummer-night.txt", "paradise-lost.txt"]),
            "paradise-lost.txt:4:With loss of Eden, till one greater Man\n"
        )

    def test_multiple_files_no_matches_various_flags(self, mock_open):
        self.assertEqual(
            grep("Gandalf", "-n -l -x -i", ["iliad.txt", "midsummer-night.txt", "paradise-lost.txt"]),
            ""
        )

    def test_multiple_files_several_matches_file_flag_takes_precedence(self, mock_open):
        self.assertEqual(
            grep("who", "-n -l", ["iliad.txt", "midsummer-night.txt", "paradise-lost.txt"]),
            "iliad.txt\n"
            "paradise-lost.txt\n"
        )

    def test_multiple_files_several_matches_invert_and_match_entire(self, mock_open):
        # All lines from all three files except line 4 of iliad.txt
        res = grep("Illustrious into Ades premature,", "-x -v", ["iliad.txt", "midsummer-night.txt", "paradise-lost.txt"])
        self.assertNotIn("iliad.txt:Illustrious into Ades premature,\n", res)
        self.assertIn("iliad.txt:Achilles sing, O Goddess! Peleus' son;\n", res)
        self.assertIn("midsummer-night.txt:I do entreat your grace to pardon me.\n", res)
        self.assertIn("paradise-lost.txt:Of Mans First Disobedience, and the Fruit\n", res)

if __name__ == "__main__":
    unittest.main()
